function New-ItemObj($standard, $question, $correct, $correctFeedback, $d1, $f1, $d2, $f2, $d3, $f3) {
  [pscustomobject]@{
    standard = $standard
    question = $question
    correct = $correct
    correctFeedback = $correctFeedback
    distractors = @(
      [pscustomobject]@{ text = $d1; feedback = $f1 },
      [pscustomobject]@{ text = $d2; feedback = $f2 },
      [pscustomobject]@{ text = $d3; feedback = $f3 }
    )
  }
}

function Choice($letter, $text, $feedback, $correct) {
  $prefix = if ($correct) { "=" } else { "~" }
  "$prefix$letter. $text#$feedback"
}

function GiftBlock($id, $std, $question, $choices) {
  "::$id::`nQuestion ID:<br>$id<br><br>MLA Standard:<br>$std<br><br>Question:<br>$question {`n$($choices -join "`n")`n}`n"
}

function BuildGift($items, $file, $prefix, $count) {
  $letters = @("A", "B", "C", "D")
  $blocks = @()
  for ($i = 1; $i -le $count; $i++) {
    $seed = $items[$i - 1]
    $correctIndex = ($i - 1) % 4
    $ordered = @()
    $d = 0
    for ($j = 0; $j -lt 4; $j++) {
      if ($j -eq $correctIndex) {
        $ordered += Choice $letters[$j] $seed.correct $seed.correctFeedback $true
      } else {
        $ordered += Choice $letters[$j] $seed.distractors[$d].text $seed.distractors[$d].feedback $false
        $d++
      }
    }
    $qid = "{0}_Q{1:D2}" -f $prefix, $i
    $blocks += GiftBlock $qid $seed.standard $seed.question $ordered
  }
  Set-Content -Path $file -Value ($blocks -join "`n") -NoNewline
}

function SF($q, $c, $cf, $d1, $f1, $d2, $f2, $d3, $f3) {
  New-ItemObj "Readiness Support Only" $q $c $cf $d1 $f1 $d2 $f2 $d3 $f3
}

