# Lesson 7 applications
$l7 = @()
foreach($t in @(@(6,8,10,"ramp"),@(9,12,15,"support beam"),@(12,16,20,"ladder brace"),@(15,20,25,"diagonal walkway"),@(10,24,26,"cable"))){ $a=$t[0]; $b=$t[1]; $c=$t[2]; $ctx=$t[3]; $l7 += T "MLA.GEO.TRI.5" "A $ctx forms a right triangle with legs $a ft and $b ft. What is the hypotenuse length?" "$c ft" "Use the Pythagorean Theorem; the hypotenuse is $c ft." "$($a+$b) ft" "Adding the legs does not find the hypotenuse." "$([math]::Abs($b-$a)) ft" "Subtracting the legs does not find the hypotenuse." "$($a*$b) ft" "Multiplying the legs does not find a side length." }
foreach($t in @(@(13,5,12,"ladder"),@(25,7,24,"fire escape"),@(17,8,15,"support wire"),@(29,20,21,"flagpole cable"),@(41,9,40,"tower brace"))){ $c=$t[0]; $a=$t[1]; $b=$t[2]; $ctx=$t[3]; $l7 += T "MLA.GEO.TRI.5" "A $ctx is the hypotenuse of length $c ft, and one leg is $a ft. What is the other leg?" "$b ft" "Use b<sup>2</sup> = $c<sup>2</sup> - $a<sup>2</sup>; the missing leg is $b ft." "$($c-$a) ft" "Subtracting side lengths ignores the squared relationship." "$($c+$a) ft" "Adding lengths does not solve for a missing leg." "&radic;$($c*$c+$a*$a) ft" "This adds squares even though the hypotenuse is already known." }
$l7 += T "MLA.GEO.TRI.5" "A building height h is opposite a 35&deg; angle and the horizontal distance is 50 m. Which setup fits?" "tan 35&deg; = <sup>h</sup>&frasl;<sub>50</sub>" "Tangent uses opposite over adjacent." "sin 35&deg; = <sup>50</sup>&frasl;<sub>h</sub>" "Sine uses opposite over hypotenuse, and 50 is adjacent." "cos 35&deg; = <sup>h</sup>&frasl;<sub>50</sub>" "Cosine uses adjacent over hypotenuse." "tan 35&deg; = <sup>50</sup>&frasl;<sub>h</sub>" "This reverses opposite and adjacent."
$l7 += T "MLA.GEO.TRI.5" "A ramp length r is the hypotenuse, and the rise is 4 ft with angle of elevation 20&deg;. Which setup uses sine?" "sin 20&deg; = <sup>4</sup>&frasl;<sub>r</sub>" "Sine uses opposite over hypotenuse." "cos 20&deg; = <sup>4</sup>&frasl;<sub>r</sub>" "Cosine uses adjacent over hypotenuse." "tan 20&deg; = <sup>4</sup>&frasl;<sub>r</sub>" "Tangent uses opposite over adjacent, not hypotenuse." "sin 20&deg; = <sup>r</sup>&frasl;<sub>4</sub>" "This reverses sine."
$l7 += T "MLA.GEO.TRI.5" "A diagonal path crosses a 18 m by 24 m rectangular garden. What is the path length?" "30 m" "The diagonal is the hypotenuse: 18<sup>2</sup> + 24<sup>2</sup> = 30<sup>2</sup>." "42 m" "Adding side lengths does not find the diagonal." "6 m" "Subtracting side lengths does not find the diagonal." "432 m" "Multiplying side lengths gives area, not diagonal length."
$l7 += T "MLA.GEO.TRI.5" "A kite string is 65 m long and the kite is 63 m above the ground. How far is the person horizontally from the point below the kite?" "16 m" "The string is the hypotenuse: x<sup>2</sup> + 63<sup>2</sup> = 65<sup>2</sup>, so x = 16." "2 m" "Subtracting 63 from 65 ignores the squared relationship." "128 m" "Adding the lengths does not find the horizontal distance." "&radic;8194 m" "This adds squares even though 65 is the hypotenuse."
$l7 += T "MLA.GEO.TRI.5" "A support cable makes a right triangle with opposite side 12 and adjacent side 35 relative to angle A. Which ratio finds angle A?" "tan A = <sup>12</sup>&frasl;<sub>35</sub>" "Tangent uses opposite over adjacent." "sin A = <sup>12</sup>&frasl;<sub>35</sub>" "Sine uses opposite over hypotenuse." "cos A = <sup>12</sup>&frasl;<sub>35</sub>" "Cosine uses adjacent over hypotenuse." "tan A = <sup>35</sup>&frasl;<sub>12</sub>" "This reverses tangent."
$l7 += T "MLA.GEO.TRI.5" "A zipline has horizontal distance 80 ft and vertical drop 18 ft. Which theorem finds the zipline length?" "Pythagorean Theorem" "The horizontal and vertical distances are legs of a right triangle, so the hypotenuse is found with the Pythagorean Theorem." "AA similarity" "No triangle similarity evidence is needed for this side-length problem." "Reflection symmetry" "No symmetry is involved." "Scale factor only" "No similar figure scale factor is given."
$l7 += T "MLA.GEO.TRI.5" "A right-triangle application gives an acute angle, adjacent side, and asks for hypotenuse. Which trig ratio uses adjacent and hypotenuse?" "Cosine" "Cosine is adjacent over hypotenuse." "Sine" "Sine uses opposite and hypotenuse." "Tangent" "Tangent uses opposite and adjacent." "Pythagorean only" "A trig ratio is appropriate because an angle is given."
$l7 += T "MLA.GEO.TRI.5" "A surveyor knows the angle of elevation and horizontal distance to a tree. Which side is the tree height?" "Opposite side" "The height is across from the angle of elevation." "Adjacent side" "The horizontal distance is adjacent to the angle." "Hypotenuse" "The line of sight is the hypotenuse." "Right angle" "The height is a side length, not an angle."
$l7 += T "MLA.GEO.TRI.5" "A 30-ft ladder reaches 24 ft up a wall. How far is the ladder base from the wall?" "18 ft" "The ladder is the hypotenuse: x<sup>2</sup> + 24<sup>2</sup> = 30<sup>2</sup>, so x = 18." "6 ft" "Subtracting 24 from 30 ignores squared lengths." "54 ft" "Adding lengths does not solve the right triangle." "&radic;1476 ft" "This adds squares while treating both known values as legs."
$l7 += T "MLA.GEO.TRI.5" "A diagonal of a square is 10&radic;2 units. What is the side length?" "10 units" "For a square, the diagonal is side times &radic;2, so the side is 10." "20 units" "This doubles the coefficient and does not reverse the diagonal relationship." "5 units" "This halves the coefficient without using the &radic;2 relationship." "10&radic;2 units" "That is the diagonal, not the side length."
$l7 += T "MLA.GEO.TRI.5" "A right triangle has hypotenuse 50 and one leg 14. Which setup finds the other leg x?" "x<sup>2</sup> + 14<sup>2</sup> = 50<sup>2</sup>" "The known leg and missing leg squares add to the hypotenuse square." "x<sup>2</sup> + 50<sup>2</sup> = 14<sup>2</sup>" "This incorrectly treats 14 as the hypotenuse." "x + 14 = 50" "The Pythagorean relationship uses squares." "14x = 50" "Multiplying a leg by the missing leg is not the theorem."
$l7 += T "MLA.GEO.TRI.5" "A right-triangle problem gives opposite and adjacent sides and asks for an angle. Which ratio should be used?" "Tangent" "Tangent uses opposite and adjacent." "Sine" "Sine uses opposite and hypotenuse." "Cosine" "Cosine uses adjacent and hypotenuse." "Scale factor" "Scale factor is not the trig ratio for opposite and adjacent."
